new: adds `import type { Skill } from './vocabulary.js'`, `skills: Skill[]` to PublicUser ("What the user plays or does, from the shared vocabulary.") and optional `skills?: Skill[]` to SignUpRequest ("Skills are picked on the sign-up form.").

write server/src/models/project.model.ts:
// A project: an unfinished musical idea the owner wants others to add to.
// Structure follows the clickable prototype's demo content (prototype/README.md):
// an owner, optional tags (BPM, key, genre, mood), and the kinds of
// contribution it needs, matched against the shared vocabulary.
//
// The feed lists open projects a signed-in user's skills match, most recently
// active first, so the compound index below sorts on updatedAt.
import type { ProjectDto, ProjectStatus, Skill } from '@exquisite-chorus/shared'
import { GENRES, MOODS, MUSICAL_KEYS, SKILLS } from '@exquisite-chorus/shared/vocabulary'
import { model, Schema, type HydratedDocument, type Types } from 'mongoose'

export const PROJECT_STATUSES: readonly ProjectStatus[] = ['open', 'closed']
export const TITLE_MAX = 140
export const DESCRIPTION_MAX = 2000
/** Whole beats per minute: slowest ballad to fastest punk/hardcore. */
export const BPM_MIN = 20
export const BPM_MAX = 400

export interface ProjectFields {
  owner: Types.ObjectId
  title: string
  description?: string
  bpm?: number
  /** Note + mode, e.g. 'G major'. Named musicalKey to not collide with the Keys instrument. */
  musicalKey?: string
  genre?: string
  mood?: string
  /** Skills the project is asking for; drives the skills-matched feed. */
  needs: Skill[]
  status: ProjectStatus
  /** Version of the current mix; 1 until the first contribution lands. */
  currentVersion: number
  createdAt: Date
  updatedAt: Date
}

const projectSchema = new Schema<ProjectFields>(
  {
    owner: { type: Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    title: { type: String, required: true, trim: true, minlength: 1, maxlength: TITLE_MAX },
    description: { type: String, trim: true, maxlength: DESCRIPTION_MAX },
    bpm: {
      type: Number,
      min: BPM_MIN,
      max: BPM_MAX,
      validate: {
        validator: (v: number) => Number.isInteger(v),
        message: 'BPM must be a whole number',
      },
    },
    musicalKey: { type: String, enum: [...MUSICAL_KEYS] },
    genre: { type: String, enum: [...GENRES] },
    mood: { type: String, enum: [...MOODS] },
    needs: {
      type: [String],
      enum: [...SKILLS],
      required: true,
      validate: {
        validator: (needs: string[]) => needs.length > 0,
        message: 'A project needs at least one kind of contribution',
      },
    },
    status: { type: String, enum: PROJECT_STATUSES, required: true, default: 'open' },
    currentVersion: { type: Number, required: true, default: 1 },
  },
  {
    timestamps: true,
    toJSON: {
      versionKey: false,
      transform: (_doc, ret): ProjectDto =>
        toProjectDto(ret as unknown as ProjectFields & { _id: unknown }),
    },
  },
)

// The feed: open projects by most recent activity. Routes tie-break with
// { _id: -1 }, the recordings list convention, for a stable order.
projectSchema.index({ status: 1, updatedAt: -1 })

export const Project = model<ProjectFields>('Project', projectSchema)

export type ProjectDocument = HydratedDocument<ProjectFields>

/** The client-facing shape, from a document or a lean object. */
export function toProjectDto(
  project: Pick<
    ProjectFields,
    | 'owner'
    | 'title'
    | 'description'
    | 'bpm'
    | 'musicalKey'
    | 'genre'
    | 'mood'
    | 'needs'
    | 'status'
    | 'currentVersion'
    | 'createdAt'
    | 'updatedAt'
  > & { _id: unknown },
  ownerDisplayName?: string,
): ProjectDto {
  return {
    id: String(project._id),
    ownerId: String(project.owner),
    ...(ownerDisplayName === undefined ? {} : { ownerDisplayName }),
    title: project.title,
    description: project.description ?? null,
    bpm: project.bpm ?? null,
    musicalKey: project.musicalKey ?? null,
    genre: project.genre ?? null,
    mood: project.mood ?? null,
    needs: project.needs,
    status: project.status,
    currentVersion: project.currentVersion,
    createdAt: new Date(project.createdAt).toISOString(),
    updatedAt: new Date(project.updatedAt).toISOString(),
  }
}

write server/src/models/contribution.model.ts:
// One version of a project's mix. Version 1 is the owner's original track,
// created together with the project; every later version is a contribution
// someone submitted ("pass an amended track on to new contributors"). The
// version history the project page shows is these documents, newest first.
//
// `recording` stays optional: the recording endpoints (upload/confirm) already
// exist, and a contribution links to one once that wiring is built; a lyrics
// contribution may carry only a note.
import type { ContributionDto } from '@exquisite-chorus/shared'
import { model, Schema, type HydratedDocument, type Types } from 'mongoose'

export const NOTE_MAX = 500
export const ORIGINAL_TRACK_NOTE = 'Original track'

export interface ContributionFields {
  project: Types.ObjectId
  contributor: Types.ObjectId
  /** 1 = the owner's original track; one document per version. */
  version: number
  /** What changed in this version, e.g. 'Added brushed drums'. */
  note?: string
  /** The Recording behind this version, once an upload is attached. */
  recording?: Types.ObjectId
  createdAt: Date
  updatedAt: Date
}

const contributionSchema = new Schema<ContributionFields>(
  {
    project: { type: Schema.Types.ObjectId, ref: 'Project', required: true },
    contributor: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    version: { type: Number, required: true, min: 1 },
    note: { type: String, trim: true, maxlength: NOTE_MAX },
    recording: { type: Schema.Types.ObjectId, ref: 'Recording' },
  },
  {
    timestamps: true,
    toJSON: {
      versionKey: false,
      transform: (_doc, ret): ContributionDto =>
        toContributionDto(ret as unknown as ContributionFields & { _id: unknown }),
    },
  },
)

// A real unique index (KTD13): a project can hold each version number once,
// so concurrent submissions cannot create two v2s.
contributionSchema.index({ project: 1, version: 1 }, { unique: true })

export const Contribution = model<ContributionFields>('Contribution', contributionSchema)

export type ContributionDocument = HydratedDocument<ContributionFields>

/** The client-facing shape, from a document or a lean object. */
export function toContributionDto(
  contribution: Pick<ContributionFields, 'project' | 'contributor' | 'version' | 'note' | 'recording' | 'createdAt'> & {
    _id: unknown
  },
  contributorDisplayName?: string,
): ContributionDto {
  return {
    id: String(contribution._id),
    projectId: String(contribution.project),
    contributorId: String(contribution.contributor),
    ...(contributorDisplayName === undefined ? {} : { contributorDisplayName }),
    version: contribution.version,
    note: contribution.note ?? null,
    recordingId: contribution.recording ? String(contribution.recording) : null,
    createdAt: new Date(contribution.createdAt).toISOString(),
  }
}

write server/src/models/seed.ts (initial version):
// Inserts the demo content from the clickable prototype (prototype/README.md)
// so the app has something to show before real users arrive: the same people,
// projects, tags, needs, and version histories the heuristic evaluators saw.
//
// Run from the repo root:
//   npm run seed                     # against MONGODB_URI (.env), e.g. Atlas or local MongoDB
//   npm run seed -- --in-memory      # no MongoDB needed: a throwaway in-memory database
//
// Seeding is idempotent: it first removes the demo users and everything they
// own, then re-creates it, so the script can run twice. It never touches
// accounts that are not part of the demo.
[full file: DEMO_PASSWORD = 'chorus-demo-2026'; SEED_USERS (12: Riley Chen, Maya Okafor, Theo Lindqvist, Ana Ruiz, Jules Park, Sam Adeyemi, Priya Nair, Leo Brandt, Dev Patel, Kai Mendes, Lena Fox, Noor Haddad, each with example.com email and vocabulary skills); SEED_PROJECTS (the prototype's 7: Porch Chords 92 BPM G major Folk Mellow needs Bass+Vocals; Night Bus 84 F♯ minor Lo-fi Dreamy Keys+Drums; Copper Wire 128 A minor Electronic Driving Vocals+Lyrics; Basement Waltz 104 D minor Jazz Dark Brass+Bass; Low Tide 70 E♭ major R&B Mellow Guitar+Vocals; Static Garden 140 C minor Hip-hop Dark Lyrics+Vocals; Second Wind 156 E major Rock Upbeat Drums+Bass; with descriptions and createdHoursAgo); SEED_CONTRIBUTIONS (11 version-history rows matching the prototype, version 1 = ORIGINAL_TRACK_NOTE); validateVocabulary() checking every seed value against SKILLS/GENRES/MOODS/MUSICAL_KEYS; seedDatabase(now = Date.now()) that deletes previous seed users and their projects/contributions, bcrypt-hashes the shared demo password at cost 12, creates users/projects/contributions with explicit createdAt offsets, and returns a SeedSummary; printSummary() printing counts, demo emails, and the demo password; main() with --in-memory flag (MongoMemoryServer) or dotenv + loadConfig + MONGODB_URI, helpful error suggesting --in-memory on connection failure; script-mode guard comparing import.meta.url to pathToFileURL(process.argv[1]).]
